        "name": "search-input.tsx",
        "code": "\"use client\"\n\nimport { SearchIcon, XIcon } from \"lucide-react\"\nimport { useRef } from \"react\"\n\nimport {\n  InputGroup,\n  InputGroupAddon,\n  InputGroupButton,\n  InputGroupInput,\n} from \"@/components/ui/input-group\"\n\nimport { useDebouncedInput } from \"@/components/openlmis/search-input/use-debounced-input\"\n\ntype SearchInputProps = {\n  value: string\n  /** Called once typing pauses, on Enter, on blur, and at once when cleared. */\n  onValueChange: (value: string) => void\n  placeholder?: string\n  /** Accessible name, when the placeholder alone does not say what is searched. */\n  label?: string\n  clearLabel?: string\n  /** Milliseconds of quiet before a value is reported. */\n  delay?: number\n}\n\nexport function SearchInput({\n  value,\n  onValueChange,\n  placeholder = \"Search...\",\n  label,\n  clearLabel = \"Clear Search\",\n  delay,\n}: SearchInputProps) {\n  const { draft, commit, inputProps } = useDebouncedInput(\n    value,\n    onValueChange,\n    delay\n  )\n  const input = useRef<HTMLInputElement>(null)\n\n  return (\n    <InputGroup>\n      <InputGroupAddon>\n        <SearchIcon />\n      </InputGroupAddon>\n      <InputGroupInput\n        aria-label={label ?? placeholder}\n        placeholder={placeholder}\n        ref={input}\n        type=\"text\"\n        {...inputProps}\n      />\n      {draft && (\n        <InputGroupAddon align=\"inline-end\">\n          <InputGroupButton\n            aria-label={clearLabel}\n            onClick={() => {\n              commit(\"\")\n              // The button goes away once the field is empty, so focus returns to the field.\n              input.current?.focus()\n            }}\n            // Keeps the field focused, so its blur never sends the text being cleared.\n            onMouseDown={(event) => event.preventDefault()}\n            size=\"icon-xs\"\n          >\n            <XIcon />\n          </InputGroupButton>\n        </InputGroupAddon>\n      )}\n    </InputGroup>\n  )\n}",
